import net from "node:net";import tls from "node:tls";
function encode(parts:unknown[]){return `*${parts.length}\r\n${parts.map(part=>{const value=String(part);return `$${Buffer.byteLength(value)}\r\n${value}\r\n`;}).join("")}`;}
function parse(buffer:Buffer,offset=0):{value:unknown;offset:number}|null{
  if(offset>=buffer.length)return null;const type=String.fromCharCode(buffer[offset]),end=buffer.indexOf("\r\n",offset+1);if(end<0)return null;const head=buffer.subarray(offset+1,end).toString(),next=end+2;
  if(type==="+")return {value:head,offset:next};if(type==="-")throw new Error("redis_command_failed");if(type===":")return {value:Number(head),offset:next};if(type==="$"){const length=Number(head);if(length<0)return {value:null,offset:next};if(buffer.length<next+length+2)return null;return {value:buffer.subarray(next,next+length).toString(),offset:next+length+2};}
  if(type==="*"){const length=Number(head),items=[];let cursor=next;for(let index=0;index<length;index++){const item=parse(buffer,cursor);if(!item)return null;items.push(item.value);cursor=item.offset;}return {value:items,offset:cursor};}throw new Error("redis_response_invalid");
}
export async function redisCommand(parts:unknown[]){
  if(!process.env.REDIS_URL)throw new Error("REDIS_URL is not configured.");const target=new URL(process.env.REDIS_URL),port=Number(target.port||6379);
  return new Promise<unknown>((resolve,reject)=>{let buffer=Buffer.alloc(0),settled=false;const socket=target.protocol==="rediss:"?tls.connect({host:target.hostname,port,rejectUnauthorized:true}):net.createConnection({host:target.hostname,port});const fail=(error:Error)=>{if(settled)return;settled=true;socket.destroy();reject(error);};socket.setTimeout(3000,()=>fail(new Error("redis_timeout")));socket.on("error",fail);socket.on("connect",()=>{const commands=[] as unknown[][];if(target.password)commands.push(["AUTH",decodeURIComponent(target.password)]);commands.push(parts);for(const command of commands)socket.write(encode(command));});socket.on("data",chunk=>{buffer=Buffer.concat([buffer,chunk]);try{let parsed=parse(buffer),last=parsed;if(target.password&&parsed){const second=parse(buffer,parsed.offset);if(!second)return;last=second;}if(last&&!settled){settled=true;socket.destroy();resolve(last.value);}}catch(error){fail(error instanceof Error?error:new Error("redis_response_invalid"));}});});
}
